languages.python:
def is_upper(c):
    return "A" <= c <= "Z"
def is_lower(c):
    return "a" <= c <= "z"
def is_digit(c):
    return "0" <= c <= "9"
words = []
word = ""
for i, c in enumerate(text):
    if not (is_upper(c) or is_lower(c) or is_digit(c)):
        if word:
            words.append(word.lower())
        word = ""
        continue
    prev = word[-1] if word else ""
    nxt = text[i + 1] if i + 1 < len(text) else ""
    if word and is_upper(c) and (is_lower(prev) or is_digit(prev) or (is_upper(prev) and is_lower(nxt))):
        words.append(word.lower())
        word = ""
    word += c
if word:
    words.append(word.lower())
return "".join(w if i == 0 else w[:1].upper() + w[1:] for i, w in enumerate(words))

