auto isUpper = [](char c) { return c >= 'A' && c <= 'Z'; };
auto isLower = [](char c) { return c >= 'a' && c <= 'z'; };
auto isDigit = [](char c) { return c >= '0' && c <= '9'; };
std::vector<std::string> words;
std::string word;
for (std::size_t i = 0; i < text.size(); i++) {
    char c = text[i];
    if (!isUpper(c) && !isLower(c) && !isDigit(c)) {
        if (!word.empty()) words.push_back(word);
        word.clear();
        continue;
    }
    if (!word.empty() && isUpper(c)) {
        char prev = word.back();
        char next = i + 1 < text.size() ? text[i + 1] : '\0';
        if (isLower(prev) || isDigit(prev) || (isUpper(prev) && isLower(next))) {
            words.push_back(word);
            word.clear();
        }
    }
    word += c;
}
if (!word.empty()) words.push_back(word);
for (auto& w : words) for (auto& c : w) c = static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
std::string result;
for (std::size_t i = 0; i < words.size(); i++) {
    std::string w = words[i];
    if (i) w[0] = static_cast<char>(std::toupper(static_cast<unsigned char>(w[0])));
    result += w;
}
return result;

