var words = new java.util.ArrayList<String>();
var word = new StringBuilder();
for (int i = 0; i < text.length(); i++) {
    char c = text.charAt(i);
    boolean upper = c >= 'A' && c <= 'Z';
    if (!upper && !(c >= 'a' && c <= 'z') && !(c >= '0' && c <= '9')) {
        if (word.length() > 0) words.add(word.toString().toLowerCase(java.util.Locale.ROOT));
        word.setLength(0);
        continue;
    }
    if (word.length() > 0 && upper) {
        char prev = word.charAt(word.length() - 1);
        char next = i + 1 < text.length() ? text.charAt(i + 1) : '\0';
        if ((prev >= 'a' && prev <= 'z') || (prev >= '0' && prev <= '9') || (prev >= 'A' && prev <= 'Z' && next >= 'a' && next <= 'z')) {
            words.add(word.toString().toLowerCase(java.util.Locale.ROOT));
            word.setLength(0);
        }
    }
    word.append(c);
}
if (word.length() > 0) words.add(word.toString().toLowerCase(java.util.Locale.ROOT));
var result = new StringBuilder();
for (int i = 0; i < words.size(); i++) {
    String w = words.get(i);
    result.append(i == 0 ? w : Character.toUpperCase(w.charAt(0)) + w.substring(1));
}
return result.toString();

languages.go:
isUpper := func(c byte) bool { return c >= 'A' && c <= 'Z' }
isLower := func(c byte) bool { return c >= 'a' && c <= 'z' }
isDigit := func(c byte) bool { return c >= '0' && c <= '9' }
words := []string{}
word := []byte{}
for i := 0; i < len(text); i++ {
	c := text[i]
	if !isUpper(c) && !isLower(c) && !isDigit(c) {
		if len(word) > 0 {
			words = append(words, strings.ToLower(string(word)))
		}
		word = word[:0]
		continue
	}
	if len(word) > 0 && isUpper(c) {
		prev := word[len(word)-1]
		var next byte
		if i+1 < len(text) {
			next = text[i+1]
		}
		if isLower(prev) || isDigit(prev) || (isUpper(prev) && isLower(next)) {
			words = append(words, strings.ToLower(string(word)))
			word = word[:0]
		}
	}
	word = append(word, c)
}
if len(word) > 0 {
	words = append(words, strings.ToLower(string(word)))
}
result := ""
for i, w := range words {
	if i > 0 {
		w = strings.ToUpper(w[:1]) + w[1:]
	}
	result += w
}
return result
